function texto(valor) {
  if (valor === null || valor === undefined) return '';
  return String(valor).trim();
}

function limparQuebras(valor) {
  return texto(valor)
    .replace(/\r?\n|\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function escaparCSV(valor) {
  const valorTexto = limparQuebras(valor);

  // Escapa aspas duplas
  const valorEscapado = valorTexto.replace(/"/g, '""');

  // Sempre coloca entre aspas para evitar problemas com separador, acentos e quebras
  return `"${valorEscapado}"`;
}

function doisDigitos(numero) {
  return String(numero).padStart(2, '0');
}

function dataHojeE3MesesAtrasBrasilia() {
  const partes = new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  }).formatToParts(new Date());

  const mapa = {};

  for (const parte of partes) {
    mapa[parte.type] = parte.value;
  }

  const hoje = {
    dia: Number(mapa.day),
    mes: Number(mapa.month),
    ano: Number(mapa.year)
  };

  function ultimoDiaDoMes(ano, mes) {
    // mes aqui vai de 1 a 12
    return new Date(ano, mes, 0).getDate();
  }

  let mesInicial = hoje.mes - 3;
  let anoInicial = hoje.ano;

  if (mesInicial <= 0) {
    mesInicial += 12;
    anoInicial -= 1;
  }

  const ultimoDiaInicial = ultimoDiaDoMes(anoInicial, mesInicial);
  const diaInicial = Math.min(hoje.dia, ultimoDiaInicial);

  return {
    inicio: {
      dia: doisDigitos(diaInicial),
      mes: doisDigitos(mesInicial),
      ano: String(anoInicial)
    },
    fim: {
      dia: doisDigitos(hoje.dia),
      mes: doisDigitos(hoje.mes),
      ano: String(hoje.ano)
    }
  };
}

// ================================
// CONFIGURAÇÕES
// ================================

// Separador ideal para abrir no Excel em português brasileiro
const SEPARADOR = ';';

const periodo = dataHojeE3MesesAtrasBrasilia();

const nomeArquivo =
  `relatorio_consolidado_${periodo.inicio.dia}.${periodo.inicio.mes}_${periodo.fim.dia}.${periodo.fim.mes}.${periodo.fim.ano}.csv`;

// Se quiser forçar ordem específica de colunas, preencha aqui (ex.: 'Cod Componente', 'Descricao', ...).
// Se deixar vazio, o código pega automaticamente todas as colunas encontradas.
const COLUNAS_FIXAS = [];

// ================================
// LER TODOS OS ITENS DE ENTRADA
// ================================

const linhas = $input.all().map(item => item.json);

// ================================
// SE NÃO HOUVER LINHAS
// ================================

if (linhas.length === 0) {
  const csvVazio = '\uFEFFNenhum dado encontrado';

  return [
    {
      json: {
        arquivo: nomeArquivo,
        total_linhas: 0,
        mensagem: 'CSV gerado sem dados.',
        periodo_inicio: `${periodo.inicio.dia}/${periodo.inicio.mes}/${periodo.inicio.ano}`,
        periodo_fim: `${periodo.fim.dia}/${periodo.fim.mes}/${periodo.fim.ano}`
      },
      binary: {
        data: {
          data: Buffer.from(csvVazio, 'utf8').toString('base64'),
          mimeType: 'text/csv',
          fileName: nomeArquivo,
          fileExtension: 'csv'
        }
      }
    }
  ];
}

// ================================
// DEFINIR COLUNAS
// ================================

let colunas = [];

if (COLUNAS_FIXAS.length > 0) {
  colunas = COLUNAS_FIXAS;
} else {
  const conjuntoColunas = new Set();

  for (const linha of linhas) {
    for (const chave of Object.keys(linha)) {
      conjuntoColunas.add(chave);
    }
  }

  colunas = Array.from(conjuntoColunas);
}

// ================================
// MONTAR CSV
// ================================

const cabecalho = colunas
  .map(coluna => escaparCSV(coluna))
  .join(SEPARADOR);

const corpo = linhas.map(linha => {
  return colunas
    .map(coluna => escaparCSV(linha[coluna]))
    .join(SEPARADOR);
}).join('\n');

// BOM no começo ajuda o Excel a reconhecer acentos corretamente
const csv = '\uFEFF' + cabecalho + '\n' + corpo;

// ================================
// RETORNAR ARQUIVO BINÁRIO PARA EMAIL
// ================================

return [
  {
    json: {
      arquivo: nomeArquivo,
      total_linhas: linhas.length,
      total_colunas: colunas.length,
      periodo_inicio: `${periodo.inicio.dia}/${periodo.inicio.mes}/${periodo.inicio.ano}`,
      periodo_fim: `${periodo.fim.dia}/${periodo.fim.mes}/${periodo.fim.ano}`,
      mensagem: `CSV gerado com ${linhas.length} linha(s).`
    },
    binary: {
      data: {
        data: Buffer.from(csv, 'utf8').toString('base64'),
        mimeType: 'text/csv',
        fileName: nomeArquivo,
        fileExtension: 'csv'
      }
    }
  }
];
